def SierpinskiNumber (k : Nat) : Prop :=
  (0 : Nat) < k ∧ k % (2 : Nat) = (1 : Nat) ∧ ∀ (n : Nat), Nat.Composite (k * (2 : Nat) ^ n + (1 : Nat))

def OddPrimeSet (P : Finset Nat) : Prop :=
  ∀ (p : Nat), p ∈ P → p.Prime ∧ p % (2 : Nat) = (1 : Nat)

def coverPeriod (P : Finset Nat) : Nat :=
  Finset.prod P (fun (q : Nat) => q - (1 : Nat))

def TailCovered (k : Nat) (P : Finset Nat) (N : Nat) : Prop :=
  ∀ (n : Nat), n < N → ∃ (p : Nat), p ∈ P ∧ p ∣ k * (2 : Nat) ^ (n + (1 : Nat)) + (1 : Nat)

